CREATE TABLE IF NOT EXISTS product_type (id TEXT PRIMARY KEY, value TEXT NOT NULL, external_id TEXT, metadata JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), deleted_at TIMESTAMPTZ);
CREATE UNIQUE INDEX IF NOT EXISTS IDX_type_value_unique ON product_type(value) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS product_collection (id TEXT PRIMARY KEY, title TEXT NOT NULL, handle TEXT NOT NULL, external_id TEXT, metadata JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), deleted_at TIMESTAMPTZ);
CREATE UNIQUE INDEX IF NOT EXISTS IDX_collection_handle_unique ON product_collection(handle) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS product_category (id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', handle TEXT NOT NULL, mpath TEXT NOT NULL, is_active BOOLEAN NOT NULL DEFAULT false, is_internal BOOLEAN NOT NULL DEFAULT false, rank NUMERIC NOT NULL DEFAULT 0, external_id TEXT, metadata JSONB, parent_category_id TEXT REFERENCES product_category(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), deleted_at TIMESTAMPTZ);
CREATE UNIQUE INDEX IF NOT EXISTS IDX_category_handle_unique ON product_category(handle) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS IDX_product_category_path ON product_category(mpath) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS product_tag (id TEXT PRIMARY KEY, value TEXT NOT NULL, external_id TEXT, metadata JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), deleted_at TIMESTAMPTZ);
CREATE UNIQUE INDEX IF NOT EXISTS IDX_tag_value_unique ON product_tag(value) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS product (id TEXT PRIMARY KEY, title TEXT NOT NULL, handle TEXT NOT NULL, subtitle TEXT, description TEXT, is_giftcard BOOLEAN NOT NULL DEFAULT false, status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','proposed','published','rejected')), thumbnail TEXT, weight NUMERIC, length NUMERIC, height NUMERIC, width NUMERIC, origin_country TEXT, hs_code TEXT, mid_code TEXT, material TEXT, collection_id TEXT REFERENCES product_collection(id), type_id TEXT REFERENCES product_type(id), discountable BOOLEAN NOT NULL DEFAULT true, external_id TEXT, metadata JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), deleted_at TIMESTAMPTZ);
CREATE UNIQUE INDEX IF NOT EXISTS IDX_product_handle_unique ON product(handle) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS IDX_product_type_id ON product(type_id) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS IDX_product_collection_id ON product(collection_id) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS IDX_product_status ON product(status) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS product_variant (id TEXT PRIMARY KEY, title TEXT NOT NULL, sku TEXT, barcode TEXT, ean TEXT, upc TEXT, allow_backorder BOOLEAN NOT NULL DEFAULT false, manage_inventory BOOLEAN NOT NULL DEFAULT true, hs_code TEXT, origin_country TEXT, mid_code TEXT, material TEXT, weight NUMERIC, length NUMERIC, height NUMERIC, width NUMERIC, metadata JSONB, variant_rank NUMERIC DEFAULT 0, thumbnail TEXT, product_id TEXT REFERENCES product(id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), deleted_at TIMESTAMPTZ);
CREATE UNIQUE INDEX IF NOT EXISTS IDX_product_variant_sku_unique ON product_variant(sku) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS IDX_product_variant_barcode_unique ON product_variant(barcode) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS IDX_product_variant_ean_unique ON product_variant(ean) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS IDX_product_variant_upc_unique ON product_variant(upc) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS IDX_product_variant_product_id ON product_variant(product_id) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS product_option (id TEXT PRIMARY KEY, title TEXT NOT NULL, is_exclusive BOOLEAN NOT NULL DEFAULT false, metadata JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), deleted_at TIMESTAMPTZ);
CREATE UNIQUE INDEX IF NOT EXISTS IDX_product_option_global_title_unique ON product_option(title) WHERE deleted_at IS NULL AND is_exclusive=false;
CREATE TABLE IF NOT EXISTS product_option_value (id TEXT PRIMARY KEY, value TEXT NOT NULL, rank NUMERIC, metadata JSONB, option_id TEXT REFERENCES product_option(id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), deleted_at TIMESTAMPTZ);
CREATE UNIQUE INDEX IF NOT EXISTS IDX_option_value_option_id_unique ON product_option_value(option_id,value) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS product_product_option (id TEXT PRIMARY KEY, product_id TEXT NOT NULL REFERENCES product(id) ON DELETE CASCADE, product_option_id TEXT NOT NULL REFERENCES product_option(id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), deleted_at TIMESTAMPTZ);
CREATE UNIQUE INDEX IF NOT EXISTS IDX_product_product_option_unique ON product_product_option(product_id,product_option_id) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS product_product_option_value (id TEXT PRIMARY KEY, product_product_option_id TEXT NOT NULL REFERENCES product_product_option(id) ON DELETE CASCADE, product_option_value_id TEXT NOT NULL REFERENCES product_option_value(id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), deleted_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS IDX_product_product_option_value_product_product_option_id_fk ON product_product_option_value(product_product_option_id);
CREATE UNIQUE INDEX IF NOT EXISTS IDX_product_product_option_value_unique ON product_product_option_value(product_product_option_id,product_option_value_id) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS product_variant_option (variant_id TEXT NOT NULL REFERENCES product_variant(id) ON DELETE CASCADE, option_value_id TEXT NOT NULL REFERENCES product_option_value(id) ON DELETE CASCADE, PRIMARY KEY(variant_id,option_value_id));
CREATE TABLE IF NOT EXISTS image (id TEXT PRIMARY KEY, url TEXT NOT NULL, metadata JSONB, rank NUMERIC NOT NULL DEFAULT 0, product_id TEXT REFERENCES product(id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), deleted_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS product_variant_product_image (id TEXT PRIMARY KEY, variant_id TEXT NOT NULL REFERENCES product_variant(id) ON DELETE CASCADE, image_id TEXT NOT NULL REFERENCES image(id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), deleted_at TIMESTAMPTZ);
CREATE UNIQUE INDEX IF NOT EXISTS IDX_product_variant_product_image_unique ON product_variant_product_image(variant_id,image_id) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS product_tags (product_id TEXT NOT NULL REFERENCES product(id) ON DELETE CASCADE, product_tag_id TEXT NOT NULL REFERENCES product_tag(id) ON DELETE CASCADE, PRIMARY KEY(product_id,product_tag_id));
CREATE TABLE IF NOT EXISTS product_category_product (product_id TEXT NOT NULL REFERENCES product(id) ON DELETE CASCADE, product_category_id TEXT NOT NULL REFERENCES product_category(id) ON DELETE CASCADE, PRIMARY KEY(product_id,product_category_id));
ALTER TABLE product_variant_inventory_item ADD COLUMN IF NOT EXISTS required_quantity NUMERIC NOT NULL DEFAULT 1;
